-- Stage C: immutable drafts/publications and optimistic concurrency.
create table public.site_templates (
  kind text primary key check(kind in ('content','catalogue')),
  payload jsonb not null
);
create table public.site_field_definitions (
  id text primary key,
  page text not null,
  kind text not null check(kind in ('text','link','image','seo')),
  label text not null
);
create table public.site_revisions (
  id uuid primary key default gen_random_uuid(),
  version bigint generated always as identity unique,
  kind text not null references public.site_templates(kind),
  parent_id uuid references public.site_revisions(id),
  operation text not null check(operation in ('seed','draft','publication')),
  payload jsonb not null,
  created_by uuid,
  created_at timestamptz not null default now()
);
create index site_revisions_history on public.site_revisions(kind,version desc);
create table public.site_document_heads (
  kind text primary key references public.site_templates(kind),
  draft_id uuid not null references public.site_revisions(id),
  published_id uuid not null references public.site_revisions(id),
  updated_at timestamptz not null default now()
);

alter table public.site_templates enable row level security;
alter table public.site_field_definitions enable row level security;
alter table public.site_revisions enable row level security;
alter table public.site_document_heads enable row level security;
revoke all on public.site_templates,public.site_field_definitions,public.site_revisions,public.site_document_heads from anon,authenticated;
grant select on public.site_field_definitions,public.site_revisions,public.site_document_heads to authenticated;
grant all on public.site_templates,public.site_field_definitions,public.site_revisions,public.site_document_heads to service_role;
create policy site_fields_editor on public.site_field_definitions for select to authenticated using(public.app_can_manage_media());
create policy site_revision_editor on public.site_revisions for select to authenticated
 using(public.app_is_admin() or (kind='content' and public.app_staff_role()='marketing'));
create policy site_heads_editor on public.site_document_heads for select to authenticated
 using(public.app_is_admin() or (kind='content' and public.app_staff_role()='marketing'));

create function public.app_catalogue_shape_valid(value jsonb, template jsonb, field_name text default '')
returns boolean language plpgsql immutable set search_path='' as $$
declare k text; n integer;
begin
 if value is null or jsonb_typeof(value)<>jsonb_typeof(template) then return false; end if;
 if field_name in ('id','service','group','schema','rules') then return value=template; end if;
 case jsonb_typeof(template)
 when 'object' then
  if (select array_agg(x order by x) from jsonb_object_keys(value) x)
      is distinct from (select array_agg(x order by x) from jsonb_object_keys(template) x) then return false; end if;
  for k in select jsonb_object_keys(template) loop
   if not public.app_catalogue_shape_valid(value->k,template->k,k) then return false; end if;
  end loop;
 when 'array' then
  if jsonb_array_length(value)<>jsonb_array_length(template) then return false; end if;
  for n in 0..jsonb_array_length(template)-1 loop
   if not public.app_catalogue_shape_valid(value->n,template->n,field_name) then return false; end if;
  end loop;
 when 'string' then return char_length(value#>>'{}') between 1 and 300;
 when 'number' then
  if (value#>>'{}')::numeric not between 0 and 100000 then return false; end if;
  if field_name in ('price','chocolate') then return (value#>>'{}')::numeric*1000=trunc((value#>>'{}')::numeric*1000); end if;
  return (value#>>'{}')::numeric=trunc((value#>>'{}')::numeric);
 else return false;
 end case;
 return true;
exception when others then return false;
end;
$$;

create function public.app_site_payload_valid(document_kind text, value jsonb)
returns boolean language plpgsql stable security definer set search_path='' as $$
declare template jsonb; d record; v jsonb; p jsonb; previous_guests integer:=0; u text;
begin
 select payload into template from public.site_templates where kind=document_kind;
 if template is null or value is null or octet_length(value::text)>524288 then return false; end if;
 if document_kind='catalogue' then
  if not public.app_catalogue_shape_valid(value,template) then return false; end if;
  for p in select jsonb_array_elements(value->'packages') loop
   if (p->>'guests')::int not between 1 and 400 or (p->>'max')::int not between (p->>'guests')::int and 400
    or (p->>'hours')::int not between 4 and 8 or (p->>'towers')::int not between 1 and 3
    or (p->>'selections')::int not between 1 and 5 then return false; end if;
  end loop;
  for p in select jsonb_array_elements(value->'coffeePackages') loop
   if (p->>'guests')::int<=previous_guests or (p->>'guests')::int>400 then return false; end if;
   previous_guests:=(p->>'guests')::int;
  end loop;
  return true;
 end if;
 if jsonb_typeof(value)<>'object' or value->'schema'<>'1'::jsonb
  or (select array_agg(x order by x) from jsonb_object_keys(value) x)<>array['fields','schema']
  or jsonb_typeof(value->'fields')<>'object'
  or (select count(*) from jsonb_object_keys(value->'fields'))<>(select count(*) from public.site_field_definitions) then return false; end if;
 for d in select * from public.site_field_definitions loop
  v:=value->'fields'->d.id;
  if v is null or jsonb_typeof(v)<>'object' then return false; end if;
  if d.kind in ('text','seo') then
   if (select array_agg(x order by x) from jsonb_object_keys(v) x)<>array['ar','en']
    or jsonb_typeof(v->'en')<>'string' or jsonb_typeof(v->'ar')<>'string'
    or char_length(btrim(v->>'en')) not between 1 and 6000 or char_length(btrim(v->>'ar')) not between 1 and 6000 then return false; end if;
  elsif d.kind='link' then
   if (select array_agg(x order by x) from jsonb_object_keys(v) x)<>array['url'] or jsonb_typeof(v->'url')<>'string' then return false; end if;
   u:=v->>'url';
   if char_length(u) not between 1 and 2000 or u~'[[:cntrl:][:space:]\\]' or
    not (u~'^https://[^/@]+[^@]*$' or u~'^tel:\+?[0-9-]+$' or u~'^mailto:[^@[:space:]]+@[^@[:space:]]+$'
     or u~'^(index|business|catering|links)\.html(#[A-Za-z0-9_-]+)?$' or u~'^#[A-Za-z0-9_-]*$') then return false; end if;
  elsif d.kind='image' then
   if (select array_agg(x order by x) from jsonb_object_keys(v) x)<>array['alt_ar','alt_en','url']
    or jsonb_typeof(v->'url')<>'string' or jsonb_typeof(v->'alt_en')<>'string' or jsonb_typeof(v->'alt_ar')<>'string'
    or char_length(v->>'alt_en')>500 or char_length(v->>'alt_ar')>500 then return false; end if;
   u:=v->>'url';
   if not (exists(select 1 from jsonb_each(template->'fields') f join public.site_field_definitions image_field on image_field.id=f.key and image_field.kind='image' where f.value->>'url'=u)
     or u~'^private:[a-f0-9-]{36}/[a-f0-9-]{36}\.(png|jpg|webp|avif)$'
     or (u~'^published:[a-f0-9]{64}\.(png|jpg|webp|avif)$' and exists(select 1 from storage.objects o where o.bucket_id='site-media' and o.name=substring(u from 11)))) then return false; end if;
  end if;
 end loop;
 return true;
exception when others then return false;
end;
$$;
revoke all on function public.app_catalogue_shape_valid(jsonb,jsonb,text),public.app_site_payload_valid(text,jsonb) from public,anon,authenticated;

create function public.save_site_draft(document_kind text, new_payload jsonb, expected_draft_id uuid)
returns public.site_revisions language plpgsql security definer set search_path='' as $$
declare head public.site_document_heads; revision public.site_revisions;
begin
 if not (public.app_is_admin() or (document_kind='content' and public.app_staff_role()='marketing')) then
  raise exception 'Editor permission is required.' using errcode='42501'; end if;
 select * into head from public.site_document_heads where kind=document_kind for update;
 if not found then raise exception 'Document not found.' using errcode='22023'; end if;
 if head.draft_id is distinct from expected_draft_id then raise exception 'This draft changed. Reload before saving.' using errcode='40001'; end if;
 if not public.app_site_payload_valid(document_kind,new_payload) then raise exception 'Document validation failed.' using errcode='22023'; end if;
 insert into public.site_revisions(kind,parent_id,operation,payload,created_by)
  values(document_kind,head.draft_id,'draft',new_payload,auth.uid()) returning * into revision;
 update public.site_document_heads set draft_id=revision.id,updated_at=now() where kind=document_kind;
 insert into public.audit_log(actor_user_id,action,entity_type,entity_id,changes)
  values(auth.uid(),'site.draft','site_revision',revision.id,jsonb_build_object('kind',document_kind,'previous_draft',head.draft_id));
 return revision;
end;
$$;

create function public.publish_site_document(document_kind text, revision_id uuid, expected_published_id uuid, media_mappings jsonb default '{}')
returns public.site_revisions language plpgsql security definer set search_path='' as $$
declare head public.site_document_heads; draft public.site_revisions; revision public.site_revisions; payload jsonb; field record; mapped text;
begin
 if not public.app_is_admin() then raise exception 'Administrator MFA is required.' using errcode='42501'; end if;
 select * into head from public.site_document_heads where kind=document_kind for update;
 if not found then raise exception 'Document not found.' using errcode='22023'; end if;
 if head.draft_id is distinct from revision_id or head.published_id is distinct from expected_published_id then
  raise exception 'Document changed. Reload before publishing.' using errcode='40001'; end if;
 select * into draft from public.site_revisions where id=revision_id and kind=document_kind;
 payload:=draft.payload;
 if document_kind='content' then
  for field in select f.key,f.value from jsonb_each(payload->'fields') f join public.site_field_definitions d on d.id=f.key and d.kind='image' loop
   if field.value->>'url' like 'private:%' then
    mapped:=media_mappings->>(field.value->>'url');
    if mapped is null or mapped!~'^published:[a-f0-9]{64}\.(png|jpg|webp|avif)$' then raise exception 'Publish media before this draft.' using errcode='22023'; end if;
    payload:=jsonb_set(payload,array['fields',field.key,'url'],to_jsonb(mapped));
   end if;
  end loop;
 end if;
 if not public.app_site_payload_valid(document_kind,payload) then raise exception 'Publication validation failed.' using errcode='22023'; end if;
 insert into public.site_revisions(kind,parent_id,operation,payload,created_by)
  values(document_kind,revision_id,'publication',payload,auth.uid()) returning * into revision;
 update public.site_document_heads set published_id=revision.id,updated_at=now() where kind=document_kind;
 insert into public.audit_log(actor_user_id,action,entity_type,entity_id,changes)
  values(auth.uid(),'site.publish','site_revision',revision.id,jsonb_build_object('kind',document_kind,'previous_publication',head.published_id,'draft',revision_id));
 return revision;
end;
$$;
revoke all on function public.save_site_draft(text,jsonb,uuid),public.publish_site_document(text,uuid,uuid,jsonb) from public,anon;
grant execute on function public.save_site_draft(text,jsonb,uuid),public.publish_site_document(text,uuid,uuid,jsonb) to authenticated;

create function public.get_published_site() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('content_revision',c.id,'catalogue_revision',p.id,'content',c.payload,'catalogue',p.payload)
 from public.site_document_heads ch join public.site_revisions c on c.id=ch.published_id
 cross join public.site_document_heads ph join public.site_revisions p on p.id=ph.published_id
 where ch.kind='content' and ph.kind='catalogue';
$$;
revoke all on function public.get_published_site() from public;
grant execute on function public.get_published_site() to anon,authenticated,service_role;

