insert into public.site_revisions(id,kind,operation,payload) select case kind when 'content' then '10000000-0000-4000-8000-000000000001'::uuid else '10000000-0000-4000-8000-000000000002'::uuid end,kind,'seed',payload from public.site_templates;
insert into public.site_document_heads(kind,draft_id,published_id) select kind,id,id from public.site_revisions where operation='seed';
do $$ begin if not public.app_site_payload_valid('content',(select payload from public.site_templates where kind='content')) or not public.app_site_payload_valid('catalogue',(select payload from public.site_templates where kind='catalogue')) then raise exception 'Imported baseline failed validation'; end if; end $$;
